(()=>{'use strict';
const games=[{"id":"count-cargo","title":"のりものが なんだい？","genre":"かず","emoji":"🚚","desc":"のりものを かぞえて すうじを えらぼう","mode":0},{"id":"shape-port","title":"かたちの みなと","genre":"かたち","emoji":"⛵","desc":"かたちの あう みなとを えらぼう","mode":1},{"id":"color-light","title":"いろの ライト","genre":"いろ","emoji":"🚒","desc":"いろの あう ライトを つけよう","mode":2},{"id":"memory-garage","title":"おぼえて ガレージ","genre":"きおく","emoji":"🚗","desc":"ガレージの くるまを さがそう","mode":3},{"id":"sound-horn","title":"クラクション だれ？","genre":"おと","emoji":"🚙","desc":"おとの かずを きいて えらぼう","mode":4},{"id":"direction-rocket","title":"ロケットの むき","genre":"ほうこう","emoji":"🚀","desc":"やじるしの むきを えらぼう","mode":5},{"id":"order-station","title":"えきの じゅんばん","genre":"じゅんばん","emoji":"🚆","desc":"えきを じゅんばんに たどろう","mode":6},{"id":"odd-vehicle","title":"ちがう のりもの","genre":"かんさつ","emoji":"🚜","desc":"ひとつだけ ちがう ものを みつけよう","mode":7},{"id":"weather-helper","title":"おてんき たすけたい","genre":"げんいん","emoji":"🚁","desc":"おてんきに あう のりものを えらぼう","mode":8},{"id":"steer-path","title":"みちを すすもう","genre":"そうさ","emoji":"🚌","desc":"みちの まがりかたを えらぼう","mode":9}];
const game=games.find(x=>x.id===document.body.dataset.game);if(!game)return;
const $=id=>document.getElementById(id),stage=$('stage'),choices=$('choices'),hint=$('hint'),progress=$('progress');
let round=0,step=0,question=null,busy=true,epoch=0,ctx=null,voice=null;
const vehicles=[['🚗','くるま'],['🚌','バス'],['🚒','しょうぼうしゃ'],['🚑','きゅうきゅうしゃ'],['🚚','トラック'],['🚜','トラクター'],['🚆','でんしゃ'],['🚁','ヘリコプター']];
const names={'🌸':'さくら','🌳':'き','🏠':'おうち','🌉':'はし','🏫':'がっこう','●':'まる','▲':'さんかく','■':'しかく','★':'ほし','🔴':'あか','🟡':'きいろ','🟢':'みどり','🔵':'あお','⬆️':'うえ','⬇️':'した','⬅️':'ひだり','➡️':'みぎ','↰':'ひだり','↑':'まっすぐ','↱':'みぎ','🚕':'タクシー','🚜':'トラクター','🚒':'しょうぼうしゃ','🚑':'きゅうきゅうしゃ'};const spoken=DailyQuality.spoken;const shuffle=a=>[...a].sort(()=>Math.random()-.5),pick=a=>a[Math.floor(Math.random()*a.length)],wait=t=>new Promise(r=>setTimeout(r,t));
function unlock(){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume()}catch{}}
function melody(notes,vol=.023){unlock();if(!ctx)return;notes.forEach((f,i)=>{const t=ctx.currentTime+i*.105,o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.016);g.gain.exponentialRampToValueAtTime(.0001,t+.17);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.18)})}
function stop(){epoch++;DailyQuality.cancel()}
async function say(t){return DailyQuality.speak(t)}
function button(text,name,fn){const b=document.createElement('button');b.className='choice';b.innerHTML=DailyQuality.markup(text);b.setAttribute('aria-label',name||text);b.onclick=fn;choices.append(b)}
function makeQuestion(){const v=pick(vehicles),n=Math.min(4,round+2),m=game.mode;let q={answer:0,opts:[],show:'',prompt:'',feedback:'',name:v[1]};
if(m===0){const k=round+1+Math.floor(Math.random()*2);q.show=Array(k).fill(v[0]).join(' ');q.answer=k;q.opts=[1,2,3,4,5,6];q.prompt=v[1]+'を かぞえよう。 なんだい？ おなじ かずの すうじを おしてね';q.feedback=k+'だい だね'}
if(m===1){const a=[['●','まる'],['▲','さんかく'],['■','しかく'],['★','ほし']];const x=pick(a);q.show=x[0]+'  →  ⚓';q.answer=x[0];q.opts=shuffle(a).slice(0,n+1).map(z=>z[0]);if(!q.opts.includes(q.answer))q.opts[0]=q.answer;q.prompt='これは '+x[1]+' だね。 おなじ '+x[1]+'の かたちを おしてね';q.feedback=x[1]+'だね'}
if(m===2){const a=[['🔴','あか'],['🟡','きいろ'],['🟢','みどり'],['🔵','あお']];const x=pick(a);q.show='🚒  💡 '+x[0];q.answer=x[0];q.opts=shuffle(a).slice(0,n+1).map(z=>z[0]);if(!q.opts.includes(q.answer))q.opts[0]=q.answer;q.prompt='ライトは '+x[1]+' だね。 '+x[1]+'の ボタンを おしてね';q.feedback=x[1]+'が ひかったね'}
if(m===3){const a=shuffle(vehicles).slice(0,Math.min(4,round+2)),x=pick(a);q.show=a.map(z=>z[0]).join('   ');q.answer=a.indexOf(x)+1;q.opts=a.map((z,i)=>i+1);q.prompt=x[1]+'を さがそう。 ひだりから なんばんめかな？ すうじを おしてね';q.feedback=x[1]+'を みつけたね';q.optionLabels=Object.fromEntries(a.map((z,i)=>[i+1,z[0]]));q.optionNames=Object.fromEntries(a.map((z,i)=>[i+1,z[1]]));q.prompt=x[1]+'が ガレージに いるよ。 '+x[1]+'の えを おしてね';q.memory=false}
if(m===4){const k=round+1;q.show='🔊  📯  '+v[0];q.answer=k;q.opts=[1,2,3,4];q.prompt=v[1]+'の クラクションを きこう。 '+Array(k).fill('プップー').join('、')+'。 なんかい きこえたかな？ すうじを おしてね';q.feedback=k+'かい きこえたね'}
if(m===5){const a=[['⬆️','うえ'],['⬇️','した'],['⬅️','ひだり'],['➡️','みぎ']];const x=pick(a);q.show='🚀  '+x[0];q.answer=x[0];q.opts=shuffle(a).slice(0,n+1).map(z=>z[0]);if(!q.opts.includes(q.answer))q.opts[0]=q.answer;q.prompt='やじるしは '+x[1]+' だね。 '+x[1]+'の やじるしを おしてね';q.feedback=x[1]+'に すすんだね'}
if(m===6){const a=shuffle(['🌸','🌳','🏠','🌉','🏫']).slice(0,round+2);q.sequence=a;q.show='🚆  →  '+a.map((x,i)=>i<step?'⭐':x).join(' → ');q.answer=a[step];q.opts=shuffle([...a.slice(step),...['🌸','🌳','🏠','🌉','🏫'].filter(x=>!a.includes(x))]).slice(0,n+1);if(!q.opts.includes(q.answer))q.opts[0]=q.answer;q.prompt='つぎの えきは '+spoken(a[step])+' だよ。 '+spoken(a[step])+'の マークを おしてね';q.feedback='えきに ついたよ';q.multistep=true}
if(m===7){const a=shuffle(vehicles).slice(0,2);const count=round+3;const k=Math.floor(Math.random()*count);q.show=Array.from({length:count},(_,i)=>i===k?a[1][0]:a[0][0]).join('  ');q.answer=k+1;q.opts=Array.from({length:count},(_,i)=>i+1);q.prompt='ひとつだけ ちがう '+a[1][1]+'が いるよ。 ひだりから なんばんめかな？ すうじを おしてね';q.feedback=a[1][1]+'を みつけたね';q.optionLabels=Object.fromEntries(Array.from({length:count},(_,i)=>[i+1,i===k?a[1][0]:a[0][0]]));q.optionNames=Object.fromEntries(Array.from({length:count},(_,i)=>[i+1,i===k?a[1][1]:a[0][1]]));q.prompt=a[0][1]+'の なかに、'+a[1][1]+'が いるよ。 '+a[1][1]+'の えを おしてね'}
if(m===8){const a=[['☔','あめ','🚕','タクシー'],['❄️','ゆき','🚜','ゆきかきしゃ'],['🔥','かじ','🚒','しょうぼうしゃ'],['🏥','びょういん','🚑','きゅうきゅうしゃ']];const x=pick(a);q.show=x[0]+'  '+x[1]+'  ❓';q.answer=x[2];q.opts=shuffle(a).slice(0,n+1).map(z=>z[2]);if(!q.opts.includes(q.answer))q.opts[0]=q.answer;q.prompt=x[1]+'で こまっているよ。 '+x[3]+'が ひつようだね。 '+x[3]+'を おしてね';q.feedback=x[3]+'が きたね';q.optionNames={'🚕':'タクシー','🚜':'ゆきかきしゃ','🚒':'しょうぼうしゃ','🚑':'きゅうきゅうしゃ'}}
if(m===9){const a=[['↰','ひだり'],['↑','まっすぐ'],['↱','みぎ']];const x=pick(a);q.show='🚌   🛣️  '+x[0];q.answer=x[0];q.opts=shuffle(a).map(z=>z[0]);q.prompt='バスは '+x[1]+'に すすむよ。 '+x[1]+'の やじるしを おしてね';q.feedback=x[1]+'に すすめたね'}
q.opts=m===0?[1,2,3,4]:(m===3||m===4||m===7?[...new Set(q.opts)].sort((a,b)=>a-b):[...new Set(q.opts)]);if(!q.opts.includes(q.answer))q.opts.push(q.answer);if(q.opts.every(x=>typeof x==='number'))q.opts.sort((a,b)=>a-b);return q}
function render(){stage.innerHTML=DailyQuality.markup(question.show);choices.innerHTML='';DailyQuality.ordered(question.opts).forEach(x=>{button(question.optionLabels?.[x]||String(x),question.optionNames?.[x]||spoken(x),()=>answer(x));choices.lastChild.dataset.value=x;});progress.textContent=(round+1)+' / 3'+(question.multistep?'　'+(step+1)+' / '+question.sequence.length:'');DailyQuality.state('speaking',round,step)}
async function startRound(){stop();busy=true;step=0;question=makeQuestion();render();const e=epoch;await say(question.prompt);if(e!==epoch)return;busy=false;DailyQuality.state('play',round,step)}
function celebrate(){stage.classList.add('success');const s=document.createElement('span');s.className='spark';s.textContent='✦ ✦ ✦';stage.append(s);setTimeout(()=>{s.remove();stage.classList.remove('success')},850)}
async function answer(x){if(busy)return;unlock();busy=true;const e=epoch;DailyQuality.state('speaking',round,step);const b=[...choices.children].find(b=>b.dataset.value===String(x));if(x!==question.answer){melody([392,440],.012);b?.classList.add('oops');document.body.dataset.result='retry';await say('これは '+(question.optionNames?.[x]||spoken(x))+' だね。 '+question.prompt);if(e!==epoch)return;b?.classList.remove('oops');busy=false;DailyQuality.state('play',round,step);return}
melody([523,659,784]);b?.classList.add('right');celebrate();document.body.dataset.result='correct';await say('できた！ '+question.feedback);if(e!==epoch)return;if(question.multistep&&step<question.sequence.length-1){step++;question.answer=question.sequence[step];question.show='🚆 → '+question.sequence.map((v,i)=>i<step?'✓':v).join(' → ');question.opts=question.sequence;question.prompt='つぎの えきは '+spoken(question.answer)+' だよ。 '+spoken(question.answer)+'の マークを おしてね';render();await say(question.prompt);if(e!==epoch)return;busy=false;DailyQuality.state('play',round,step);return}
round++;if(round<3){await wait(380);if(e===epoch)await startRound()}else finish()}
async function finish(){stop();busy=true;const e=epoch;DailyQuality.state('complete',3);melody([523,659,784,1047,784,1175],.027);stage.textContent='✦　✦　✦';choices.innerHTML='';progress.textContent='3 / 3';await say('ぜんぶ できたね！ すごいね！');if(e!==epoch)return;button('もういちど','もういちど',()=>{round=0;startRound()});button('ゲームいちらん','ゲームいちらん',()=>location.href='../../index.html');busy=false}
function intro(){stop();busy=true;question=null;DailyQuality.state('intro',0);stage.innerHTML=DailyQuality.markup(game.emoji);hint.textContent=game.desc;progress.textContent='あそびかた';choices.innerHTML='';button('せつめいを きく','せつめいを きく',()=>{unlock();say(game.desc+'。'+introText())});button('はじめる','ゲームを はじめる',()=>{unlock();startRound()})}
function introText(){return {3:'えは きえないよ。さがす くるまの えを おしてね。',6:'つぎの えきの なまえを きこう。おなじ マークを おしてね。',7:'ちがう のりものの えを おしてね。'}[game.mode]||'なまえを きいて、したの ボタンを おしてね。'}
$('title').textContent=game.title;document.title=game.title;$('repeat').onclick=async()=>{unlock();if(busy||!question)return;busy=true;const e=epoch;DailyQuality.state('speaking',round,step);await say(question.prompt);if(e===epoch){busy=false;DailyQuality.state('play',round,step)}};$('again').onclick=()=>{round=0;intro()};addEventListener('pagehide',stop);intro();
})();
